buildSettings.insert:

// Enable Objective-C exceptions
GCC_ENABLE_OBJC_EXCEPTIONS = YES

// Enable ARC (Automatic Reference Counting)
CLANG_ENABLE_OBJC_ARC = YES

// C++ language standard
CLANG_CXX_LANGUAGE_STANDARD = gnu++17

// Disable bitcode (TapTapSDK doesn't support bitcode)
ENABLE_BITCODE = NO

// Set minimum iOS version (UE 5.7 requires iOS 15+)
IPHONEOS_DEPLOYMENT_TARGET = 15.0


// Other linker flags - required for ObjC category loading
// (BridgeCloudSaveService uses ObjC class methods + protocol conformance,
//  -ObjC ensures static archive symbols are pulled into the final binary)
OTHER_LDFLAGS = $(inherited) -ObjC
